function fmtDate(s) {
  const d = new Date(s + "T12:00:00");
  return d.toLocaleDateString(undefined, { month:"short", day:"numeric", year:"numeric" });
}

function byRace(raceNo) {
  return WEEKLY.filter(w => Number(w.raceNumber) === Number(raceNo));
}

function mergedWeeklyForRace(raceNo) {
  const raceRows = byRace(raceNo).map(r => ({...r}));
  const overrides = MANUAL_PICKS[String(raceNo)] || {};
  raceRows.forEach(row => {
    const custom = overrides[row.player];
    if (custom && custom.some(v => v !== "" && v !== null && v !== undefined)) {
      row.picks = custom;
      row.finishes = [null,null,null];
      row.points = [null,null,null];
      row.weeklyTotal = row.weeklyTotal || 0;
    }
  });
  return raceRows;
}

function table(headers, rows) {
  return `<table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join("")}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join("")}</tr>`).join("")}</tbody></table>`;
}

function renderPodium() {
  const top3 = [...STANDINGS].sort((a,b)=>b.seasonPoints-a.seasonPoints).slice(0,3);
  document.getElementById("podium").innerHTML = top3.map((p, i) => `
    <div class="podium-card ${i===0?'first':''}">
      <div class="place">${["1st","2nd","3rd"][i]} in points</div>
      <div class="player-name">${p.player}</div>
      <div class="player-score">${p.seasonPoints}</div>
      <div class="mini">Wins: ${p.wins} · Best week: ${p.bestWeek} · Last race: ${p.lastRaceScore}</div>
    </div>`).join("");
}

function renderStandings() {
  const rows = [...STANDINGS]
    .sort((a,b)=>b.seasonPoints-a.seasonPoints)
    .map((s, i) => [
      `<span class="rank-badge">${i+1}</span>`,
      `<strong>${s.player}</strong>`,
      s.seasonPoints,
      s.wins,
      s.averageWeek?.toFixed ? s.averageWeek.toFixed(1) : s.averageWeek,
      s.bestWeek,
      s.lastRaceScore
    ]);
  document.getElementById("standings").innerHTML = table(
    ["Rank","Player","Points","Wins","Avg Week","Best Week","Last Race"],
    rows
  );
}

function renderSnapshot(completedLeagueRaces) {
  const pot = PLAYERS.length * 5;
  const leader = [...STANDINGS].sort((a,b)=>b.seasonPoints-a.seasonPoints)[0];
  document.getElementById("snapshot").innerHTML = `
    <div class="stat"><div class="muted">Players</div><div class="n">${PLAYERS.length}</div></div>
    <div class="stat"><div class="muted">Entry / Race</div><div class="n">$5</div></div>
    <div class="stat"><div class="muted">Weekly Pot</div><div class="n">$${pot}</div></div>
    <div class="stat"><div class="muted">League Races Complete</div><div class="n">${completedLeagueRaces}</div></div>
    <div class="stat"><div class="muted">Current Leader</div><div class="n" style="font-size:24px">${leader.player}</div></div>
    <div class="stat"><div class="muted">Leader Score</div><div class="n">${leader.seasonPoints}</div></div>
  `;
}

function renderTrackCard(raceNo) {
  const details = TRACK_DETAILS[String(raceNo)];
  const race = SCHEDULE.find(r => Number(r.raceNumber) === Number(raceNo));
  document.getElementById("featuredRaceName").textContent = race?.raceName || "Race Shed Fantasy";
  document.getElementById("featuredRaceMeta").textContent = `${details?.location || ""} · ${fmtDate(race.date)}`;
  document.getElementById("featuredRaceBroadcast").textContent = details?.broadcast || "Broadcast TBA";
  document.getElementById("trackTitle").textContent = details?.trackName || race?.raceName || "Track";
  document.getElementById("trackFacts").innerHTML = `
    <div class="fact"><span>Location</span><span>${details?.location || "-"}</span></div>
    <div class="fact"><span>Track Type</span><span>${details?.trackType || "-"}</span></div>
    <div class="fact"><span>Surface</span><span>${details?.surface || "-"}</span></div>
    <div class="fact"><span>Banking</span><span>${details?.banking || "-"}</span></div>
    <div class="fact"><span>Distance</span><span>${details?.distance || "-"}</span></div>
  `;
  document.getElementById("raceNotes").innerHTML = (details?.notes || ["No notes yet."]).map(n => `<div class="note"><strong>Vegas outlook</strong>${n}</div>`).join("")
    + `<div class="footerhint">Commissioner update: edit <code>MANUAL_PICKS</code> in <code>app.js</code>, commit to GitHub, and the site refreshes after Vercel redeploys.</div>`;
}

function renderWeeklyPicks(raceNo) {
  const picks = mergedWeeklyForRace(raceNo);
  document.getElementById("weeklyPicksCards").innerHTML = picks.map(p => {
    const allBlank = !(p.picks || []).some(v => v !== "" && v !== null && v !== undefined);
    return `
      <div class="pick-card">
        <div class="pick-row-top">
          <div>
            <div class="place">${p.player}</div>
            <div class="mini">${allBlank ? "Awaiting picks" : "Submitted picks"} </div>
          </div>
          <div class="total-pill">${p.weeklyTotal || 0} pts</div>
        </div>
        <div class="driver-chips">
          ${
            (p.picks || ["","",""]).map(v => 
              `<span class="chip ${v === "" || v == null ? "empty" : ""}">${v === "" || v == null ? "TBD" : "#" + v}</span>`
            ).join("")
          }
        </div>
      </div>`;
  }).join("");
}

function renderResults(raceNo) {
  const raceResults = RESULTS.filter(r => Number(r.raceNumber) === Number(raceNo))
    .sort((a,b)=>a.finish-b.finish)
    .slice(0,12);
  document.getElementById("raceResultsCards").innerHTML = raceResults.map(r => `
    <div class="result-card">
      <div class="result-row-top">
        <div>
          <div class="place">Finish ${r.finish}</div>
          <div class="player-name" style="font-size:28px; margin:4px 0 0">#${r.carNumber}</div>
        </div>
        <div class="finish-pill">${r.finishPoints} pts</div>
      </div>
    </div>
  `).join("");
}

function renderSchedule(nextRaceNo) {
  const completedRaceSet = new Set(
    WEEKLY.filter(w => Number(w.weeklyTotal) > 0).map(w => Number(w.raceNumber))
  );
  document.getElementById("schedule").innerHTML = table(
    ["Race","Date","Status"],
    SCHEDULE.map(r => {
      let status = '<span class="status future">Upcoming</span>';
      if (completedRaceSet.has(Number(r.raceNumber))) status = '<span class="status done">League complete</span>';
      if (Number(r.raceNumber) === Number(nextRaceNo)) status = '<span class="status next">Next up</span>';
      return [r.raceName, fmtDate(r.date), status];
    })
  );
}

(function init() {
  const defaultRaceNo = 5;
  const completedLeagueRaces = new Set(WEEKLY.filter(w => Number(w.weeklyTotal) > 0).map(w => w.raceNumber)).size;
  renderPodium();
  renderStandings();
  renderSnapshot(completedLeagueRaces);

  const select = document.getElementById("raceSelect");
  SCHEDULE.forEach(r => {
    const o = document.createElement("option");
    o.value = r.raceNumber;
    o.textContent = `${r.raceNumber}. ${r.raceName}`;
    if (Number(r.raceNumber) === Number(defaultRaceNo)) o.selected = true;
    select.appendChild(o);
  });

  function rerender(raceNo) {
    renderTrackCard(raceNo);
    renderWeeklyPicks(raceNo);
    renderResults(raceNo);
    renderSchedule(defaultRaceNo);
  }

  select.addEventListener("change", e => rerender(Number(e.target.value)));
  rerender(defaultRaceNo);
})();
